def clean_document(text: str):
    """Apply the three medicines in order. Returns (action, text, reasons).
    Every disease that fires is listed in reasons, even when another one already drops the file."""
    reasons, drop = [], False
    t = text
    a, t1 = fix_b3(text)
    if a == "drop":
        return "drop", text, ["B3-unfixable"]
    if a == "fix":
        reasons.append("B3")
        t = t1
    if drop_generated(t)[0] == "drop":
        reasons.append("E1")
        drop = True
    if drop_blob(t)[0] == "drop":
        reasons.append("E2")
        drop = True
    a, t2 = strip_licence_header(t)
    if a == "drop":
        reasons.append("E4-restrictive")
        drop = True
    elif a == "fix":
        reasons.append("E4")
        t = t2
    a, t3 = fix_placeholders(t)
    if a == "drop":
        reasons.append("B4-code")
        drop = True
    elif a == "fix":
        reasons.append("B4")
        t = t3
    if drop:
        return "drop", text, reasons
    return ("fix" if reasons else "keep"), t, reasons


